import{z as n,x as i,o as e,c as d,q as r,j as l,D as A,d as t,s as o,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"TOTP 与 MFA","description":"","frontmatter":{"title":"TOTP 与 MFA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/totp-mfa.md","filePath":"cs/totp-mfa.md","lastUpdated":1791413859000}'),p={name:"cs/totp-mfa.md"};function C(T,a,D,m,h,F){const B=i("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="totp-与-mfa" tabindex="-1">TOTP 与 MFA <a class="header-anchor" href="#totp-与-mfa" aria-label="Permalink to &quot;TOTP 与 MFA&quot;">​</a></h1><div class="epigraph"><p>TOTP 把共享种子和时钟窗收成六位数字。它防的是「只要口令」的重放，防不住实时钓鱼与种子备份泄漏。MFA 的强度取决于第二因素是否与第一因素一起被骗。</p><footer>—— RFC 6238；RFC 4226 HOTP；NIST SP 800-63B</footer></div><p>上一课<a href="/cs/webauthn-fido2">WebAuthn</a>给出抗钓鱼方向。缺口是<strong>仍占主导的第二因素</strong>：短信、TOTP、推送。本课钉 TOTP 合同与 MFA 的威胁模型，不写种子提取步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态口令泄漏后长期可用。TOTP：HMAC 种子 + 时间步。窗口过大则重放窗变宽；种子进截图与密码库同步则第二因素退化。短信 SS7 不在本课展开，只点名「电话号码不是认证器」。</p><p><span class="marginnote">术语翻译：TOTP 就是「共享密钥 + 当前时间」算出的一段六位短码，每 30 秒换一次——相当于把口令切成 30 秒就作废的碎片，捡到旧碎片也没用。</span></p><h3 id="mfa-疲劳" tabindex="-1">MFA 疲劳 <a class="header-anchor" href="#mfa-疲劳" aria-label="Permalink to &quot;MFA 疲劳&quot;">​</a></h3><p>反复推送可能逼出一次同意。策略应是数字匹配或 WebAuthn，而不是无限推送。</p><p><span class="marginnote">RFC 6238。NIST 800-63B 限制短信。本课禁止生成伪造 TOTP 的操作指南。时钟来自先前漂移课的粗同步。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写验证：允许 ±1 步、一次性使用、种子只在登记时显示。对照 WebAuthn：无共享种子。账户恢复仍是最弱环。</p><p><span class="marginnote">常见误区：以为手机时间和服务器差一秒就登不上。实际允许 ±1 步窗口，即上一个 30 秒窗口生成的码通常也收——所以时钟漂几十秒一般不影响登录，但窗口每放宽一步，重放有效期就多 30 秒。</span></p>',13)),(e(),l(s,null,{default:A(()=>[o(B,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEED%5B%22%E5%85%B1%E4%BA%AB%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20HMAC%5B%22HMAC%20%E6%97%B6%E9%97%B4%E6%AD%A5%22%5D%0A%20%20HMAC%20--%3E%20CODE%5B%22%E7%9F%AD%E7%A0%81%22%5D%0A%20%20CODE%20--%3E%20WIN%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E7%AA%97%E9%AA%8C%22%5D%0A%20%20PHISH%5B%22%E5%AE%9E%E6%97%B6%E9%92%93%E9%B1%BC%22%5D%20-.-%3E%7C%22%E7%94%A8%E6%88%B7%E4%B8%80%E8%B5%B7%E8%BE%93%E5%85%A5%22%7C%20CODE%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"第二因素把「只要口令库」变成「还要第二通道」。实时中间人仍可转发短码。密码破解下一课回到第一因素：口令如何被离线猜。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：实时中间人像替你接电话的传话员——你念的验证码，他原样复述给真客服。码是真的、时效也对，只是念的人和听的场景都被调包了。")],-1)),(e(),l(s,null,{default:A(()=>[o(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E6%8B%BF%E5%88%B0%E5%8F%A3%E4%BB%A4%22%5D%20--%3E%20B%7B%22%E8%83%BD%E5%AE%9E%E6%97%B6%E4%B8%8E%E4%BD%A0%E4%BA%A4%E4%BA%92%E5%90%97%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E5%8F%AA%E6%9C%89%E6%B3%84%E9%9C%B2%E7%9A%84%E5%8F%A3%E4%BB%A4%E5%BA%93%22%7C%20C%5B%22%E7%A6%BB%E7%BA%BF%E7%8C%9C%E8%A7%A3%3Cbr%2F%3ETOTP%20%E5%85%AD%E4%BD%8D%E7%A0%81%E6%8C%A1%E4%BD%8F%22%5D%0A%20%20B%20--%3E%7C%22%E6%98%AF%EF%BC%8C%E9%92%93%E9%B1%BC%E7%AB%99%E4%BB%A3%E7%90%86%22%7C%20D%5B%22%E4%BD%A0%E5%BD%93%E5%9C%BA%E8%BE%93%E5%85%A5%E7%9F%AD%E7%A0%81%3Cbr%2F%3E%E6%94%BB%E5%87%BB%E8%80%85%E5%8D%B3%E6%97%B6%E8%BD%AC%E5%8F%91%3Cbr%2F%3ETOTP%20%E5%A4%B1%E6%95%88%22%5D%0A%20%20A%20--%3E%20E%5B%22%E6%94%B9%E8%B5%B0%E8%B4%A6%E6%88%B7%E6%81%A2%E5%A4%8D%E6%B5%81%E7%A8%8B%3Cbr%2F%3E%E7%9F%AD%E4%BF%A1%E6%88%96%E4%BA%BA%E5%B7%A5%E5%AE%A2%E6%9C%8D%3Cbr%2F%3E%E7%AC%AC%E4%BA%8C%E5%9B%A0%E7%B4%A0%E8%A2%AB%E6%95%B4%E4%B8%AA%E8%B7%B3%E8%BF%87%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写短信劫持。密码破解下一课：哈希、盐、慢哈希。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>WebAuthn 抗钓鱼；TOTP 是共享种子短码。</li><li>窗、一次性、种子保管是合同。</li><li>实时转发与恢复流程可绕过 MFA。</li><li>下一课密码破解（防御视角）。</li><li>出处：RFC 6238；RFC 4226；NIST SP 800-63B。</li></ul>',4))])}const P=n(p,[["render",C]]);export{u as __pageData,P as default};
